/**
 * Represents a single task stored in IndexedDB via Dexie.
 *
 * Why strings for dates?
 * - `deadline` is stored as an ISO-like local datetime string ("YYYY-MM-DDTHH:mm")
 *   so it binds directly to `<input type="datetime-local">` and sorts chronologically.
 * - `createdAt` and `completedAt` are full ISO 8601 strings ("YYYY-MM-DDTHH:mm:ss.sssZ").
 */
export interface Task {
  /** Auto-incremented primary key generated by IndexedDB (`++id`) */
  id?: number;
  /** Short, actionable title of the task */
  title: string;
  /** Optional extra details or checklist notes */
  notes: string;
  /** Target completion date & time in "YYYY-MM-DDTHH:mm" format */
  deadline: string;
  /** Whether the user has finished the task */
  completed: boolean;
  /** ISO timestamp when the task was created */
  createdAt: string;
  /** ISO timestamp when the task was last marked complete (used in Phase 2 for streaks) */
  completedAt?: string;
}

/**
 * Shape required when creating a new task from the UI form.
 * `id`, `completed`, and `createdAt` are handled automatically by the database helper.
 */
export type NewTaskInput = Pick<Task, 'title' | 'notes' | 'deadline'>;

/**
 * Shape allowed when editing an existing task's fields.
 */
export type UpdateTaskInput = Partial<Pick<Task, 'title' | 'notes' | 'deadline' | 'completed'>>;
